/* 状态模拟：悬停无法静态触发。两条规则原样搬自 Reference.module.css 与 Tooltip.module.css，
   只把气泡的 position: fixed 拉回文档流（保留包含块），并取消 data-side='right' 的 translateY(-50%)。 */
.button.forceHover { background: var(--dsw-alias-interactive-bg-hover); }
.bubble.snapshotStatic { position: relative; inset: auto; transform: none; }

/* 静态快照：Modal 的 .root 在真实产品里是 portal 到 body 的 fixed 全屏层，这里改回文档流内的相对定位，
   留住它作为 .mask 绝对定位子层的包含块；高度由示例框给定，卡片自己的 600px 高度不变。 */
.root.snapshotStatic { position: relative; inset: auto; }

/* 静态快照：Modal 的 .root 在真实产品里是 portal 到 body 的 fixed 全屏层，这里改回文档流内的相对定位，
   留住它作为 .mask 绝对定位子层的包含块；高度由示例框给定，卡片自己的 600px 高度不变。 */
.root.snapshotStatic { position: relative; inset: auto; }

/* 静态快照：Modal 的 .root 在真实产品里是 portal 到 body 的 fixed 全屏层，这里改回文档流内的相对定位，
   留住它作为 .mask 绝对定位子层的包含块；高度由示例框给定，卡片自己的 600px 高度不变。 */
.root.snapshotStatic { position: relative; inset: auto; }

/* 静态快照：Toast 由 createPortal 挂到 body，position: fixed; top: 40px; left: 50%; translateX(-50%)，
   并在 3s 保持后开始 1s 淡出；这里改回文档流内的相对定位、取消位移与动画，让它在示例框里保持可见。 */
.toast.snapshotStatic { position: relative; inset: auto; transform: none; animation: none; width: max-content; max-width: 100%; }
